import React from 'react';
import './BookCard.css';
import PrimaryButton from '../../PrimaryButton/PrimaryButton';
import { useNavigate } from 'react-router-dom';
import { useBookContext } from '../../../context/BookContext';

const BookCard = ({ id }) => {
  const navigate = useNavigate();
  const { getBookById } = useBookContext();

  const book = getBookById(id);

  if (!book) {
    return <div className="book-card">Book not found.</div>;
  }

  const { title, author, description, price, image } = book;

  // Corrected the path from 'assents' to 'assets'
  const imagePath = require(`../../../assents/images/${image}`).default;

  const handleViewDetails = () => {
    navigate(`/books/${id}`);
  };

  return (
    <div className="book-card">
      <img src={imagePath} alt={title} className="book-image" />
      <h3>{title}</h3>
      <p><strong>Автор:</strong> {author}</p>
      <p><strong>Опис:</strong> {description}</p>
      <p><strong>Ціна:</strong> {price} грн</p>
      <PrimaryButton onClick={handleViewDetails}>Детальніше</PrimaryButton>
    </div>
  );
};

export default BookCard;
